def validateBinaryTreeNodes(n, leftChild, rightChild):
    parent = [-1] * n

    for i in range(n):
        l = leftChild[i]
        r = rightChild[i]

        if l != -1:
            if parent[l] != -1:
                return False
            parent[l] = i

        if r != -1:
            if parent[r] != -1:
                return False
            parent[r] = i

    root_count = 0
    for p in parent:
        if p == -1:
            root_count += 1

    if root_count != 1:
        return False

    root = parent.index(-1)

    visited = set()
    stack = [root]

    while stack:
        node = stack.pop()
        if node in visited:
            return False
        visited.add(node)

        l = leftChild[node]
        r = rightChild[node]

        if l != -1:
            stack.append(l)
        if r != -1:
            stack.append(r)

    return len(visited) == n
